export function renderDraft(owner) {
  if (!owner) throw Error('Authenticated owner required')
  return '<article class="draft-card" data-system="cedar"><h1>CEDAR_DRAFT_ONLY</h1><p>Local private drafts for ' + owner.replaceAll('<', '&lt;') + '</p></article>'
}
