from html import escape

def render_booking(guest):
    if not guest:
        raise ValueError('Guest reference required')
    return '<section class="booking-row" data-system="quartz"><h1>QUARTZ_BOOKING_ONLY</h1><p>Server-rendered booking for ' + escape(guest) + '</p></section>'

if __name__ == '__main__':
    print(render_booking('synthetic-guest'))
